    "source": "From the 70’s: Bohemian Rhapsody.",
    "claim": "Bohemian Rhapsody is the most-played 1970s song, with 32,298,690 Spotify plays.",
    "tables": {
      "d": "data/all_data.csv"
    },
    "code": "d[pd.to_numeric(d.date.str[-4:], errors='coerce').between(1970, 1979)].nlargest(1, 'count')[['artist', 'track', 'count']]"
